// HasOrganization applies the HasEdge predicate on the "organization" edge.
func HasOrganization() predicate.Clipping {
	return predicate.Clipping(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OrganizationTable, OrganizationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrganizationWith applies the HasEdge predicate on the "organization" edge with a given conditions (other predicates).
func HasOrganizationWith(preds ...predicate.Organization) predicate.Clipping {
	return predicate.Clipping(func(s *sql.Selector) {
		step := newOrganizationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasClips applies the HasEdge predicate on the "clips" edge.
func HasClips() predicate.Clipping {
	return predicate.Clipping(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ClipsTable, ClipsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasClipsWith applies the HasEdge predicate on the "clips" edge with a given conditions (other predicates).
func HasClipsWith(preds ...predicate.ClippingClip) predicate.Clipping {
	return predicate.Clipping(func(s *sql.Selector) {
		step := newClipsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Clipping) predicate.Clipping {
	return predicate.Clipping(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Clipping) predicate.Clipping {
	return predicate.Clipping(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Clipping) predicate.Clipping {
	return predicate.Clipping(sql.NotPredicates(p))
}
